.ds-pbtn-demo { min-width: 0; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 12px; padding: 12px; border-radius: 12px; background: #0c0c0d; color: #f9fafb; font-family: Inter, "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", system-ui, sans-serif; }
.ds-pbtn-sample { min-width: 0; padding: 16px; border-radius: 10px; }
.ds-pbtn-sample--dark {
  background: #151517;
  color: #f9fafb;
  --ds-brand: #5686fe;
  --ds-on-primary: #ffffff;
  --ds-font-sans: Inter, "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", system-ui, sans-serif;
  --ds-text-3: #adb2b8;
  --ds-text-4: #8c9199;
}
.ds-pbtn-sample--light {
  background: #faf8f4;
  color: #1c1a17;
  --ds-brand: #3b6fe0;
  --ds-on-primary: #ffffff;
  --ds-font-sans: Inter, "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", system-ui, sans-serif;
  --ds-text-3: #625e57;
  --ds-text-4: #6b665e;
}
.ds-pbtn-cap { margin-bottom: 14px; font: 500 10.5px/1.4 var(--ds-font-sans); letter-spacing: 0.04em; color: var(--ds-text-4); }
.ds-pbtn-note { margin: 12px 0 0; font: 400 11px/1.6 var(--ds-font-sans); color: var(--ds-text-3); }
@media (max-width: 720px) { .ds-pbtn-demo { grid-template-columns: minmax(0, 1fr); } }
/* 小号类与主按钮同特异性，主按钮在源顺序中更晚，有效高度仍为 30px。 */
.ds-pbtn-row { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; }
.ds-pbtn-btn { box-sizing: border-box; height: 30px; padding: 0 11px; border: 1px solid transparent; border-radius: 10px; background: var(--ds-brand); color: var(--ds-on-primary); font: 500 12.5px/1 var(--ds-font-sans); display: inline-flex; align-items: center; justify-content: center; gap: 6px; white-space: nowrap; cursor: pointer; transition: background .15s ease, opacity .15s ease; }
.ds-pbtn-btn:focus-visible { outline: 2px solid var(--ds-brand); outline-offset: 2px; }
.ds-pbtn-btn:disabled { opacity: .45; cursor: not-allowed; }
@media (hover: hover) and (pointer: fine) { .ds-pbtn-btn:hover:not(:disabled) { background: color-mix(in srgb, var(--ds-brand) 86%, #fff); } }

